/** Deterministic replay of the source's seeded 24-particle emitter and Euler steps.
 * Birth points are world-space snapshots. The fixed 1/60 s step is explicit;
 * upstream used its browser frame dt capped at 1/30 s. */
export function createBurst(seed=7){let next=seed;const random=()=>{next=(next*16807)%2147483647;return next/2147483647;};const particles=Array.from({length:24},()=>{const a=random()*Math.PI*2,tilt=.35+random()*.9,speed=16+random()*22;return {velocity:[Math.cos(a)*Math.sin(tilt)*speed,Math.sin(a)*Math.sin(tilt)*speed,Math.cos(tilt)*speed],delay:random()*.08,life:.3+random()*.45};});return {particles,nextSeed:next};}
/** @param {number} time Seconds since the saved emission; negative means no burst. */
export function sampleBurst(time,dial=0,seed=7){if(!(time>=0)||time>1.2)return [];const angle=dial*Math.PI/180,origin=[-7*Math.cos(angle)-11.4*Math.sin(angle),-7*Math.sin(angle)+11.4*Math.cos(angle),28.9];return createBurst(seed).particles.map((source,index)=>{const p=[...origin],v=[...source.velocity];let age=-source.delay,dead=false,clock=0;while(clock<time-1e-12){const dt=Math.min(1/60,time-clock);clock+=dt;age+=dt;if(age<0)continue;if(age>source.life){dead=true;break;}v[2]-=98*dt;for(let i=0;i<3;i++)p[i]+=v[i]*dt;if(p[2]<17.6){dead=true;break;}}return !dead&&age>=0?{index,position:p,velocity:v,tail:p.map((x,i)=>x-v[i]*.05),age,life:source.life,heat:1-age/source.life,origin}:null;}).filter(Boolean);}
